// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the candidate newOwner address; the property: reference contract reverts when newOwner==address(0),
    // so for ANY newOwner the reference either reverts exactly when newOwner==address(0) and succeeds otherwise.
    // The mutant removes the require and will *not* revert for newOwner==address(0). We detect that by calling
    // transferOwnership as the current owner and observing whether it reverted.
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no restrictive assumes so fuzzer may try zero address

        bool ok;
        // call as owner (setUp deployer is owner)
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract: transferOwnership should revert iff newOwner == address(0).
        // So the observed ok must equal (newOwner != address(0)).
        assertTrue(ok == (newOwner != address(0)));
    }
}

