        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract MUST revert when newOwner == address(0) and MUST succeed otherwise.
        // That is: ok == (newOwner != address(0))
        assertTrue(ok == (newOwner != address(0)));
    }
}

