pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed param: newOwner address to attempt transferOwnership to
    function testFuzz_property(address newOwner) public {
        // keep wide: allow any address including zero; no assume to exclude zero
        // Only the owner (this contract) can call transferOwnership in setUp-created c
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference behavior: transferOwnership should revert exactly when newOwner == address(0)
        // So for ALL inputs, ok == (newOwner != address(0)) must hold on the reference contract.
        // The buggy mutant removes the require and will allow ok == true when newOwner == address(0),
        // thus violating the property for that input.
        assertTrue(ok == (newOwner != address(0)));
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // Attempt sequence and single assertion: we check that calling setRewardDistributor
    // from the current rewardDistributor does not succeed unless that caller is also owner.
    // We express this by calling setRewardDistributor via c (which uses msg.sender of this contract),
    // so the test enforces that the current rewardDistributor cannot change it unless this contract is owner.

    // The function takes a candidate new distributor and an address that we expect to be the current distributor.
    // It performs a require that the externally visible rewardDistributor equals the provided currentDistributor
    // (so the inputs are consistent), then calls setRewardDistributor and finally asserts that
    // either the caller (this contract) was the owner, or the rewardDistributor did not change.

    function run(address currentDistributor, address newDistributor) public {
        // Ensure the suggested current distributor matches contract state
        require(c.rewardDistributor() == currentDistributor, "mismatch current distributor");

        // Save old value
        address before = c.rewardDistributor();

        // Attempt to call setRewardDistributor from this contract (msg.sender == this)
        // This will succeed on mutant M only if this contract equals currentDistributor (per mutant requirement),
        // but on original P it will succeed only if this contract is owner. We don't know owner, so we
        // assert the general relation after the call.
        bool didRevert;
        // Perform low-level call to capture revert without bubbling
        (didRevert, ) = address(c).call(abi.encodeWithSignature("setRewardDistributor(address)", newDistributor));

        address after = c.rewardDistributor();

        // The distinguishing rule: if the call did not revert and changed rewardDistributor, then this contract must be the owner.
        // This holds for original P (onlyOwner) but is violated by mutant M which allows currentDistributor to change it.
        assert(!(didRevert == false && after != before) || (c.owner() == address(this)));
    }

    // receive and fallback so this contract can be owner and receive ether if needed by external flows
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newDistributor) public payable {
        // Precondition: caller is not the owner of the contract
        require(caller != c.owner(), "caller must not be owner");
        bool reverted;
        // Attempt to call setRewardDistributor as `caller`. We simulate the call by using low-level call
        // Build calldata for setRewardDistributor(address)
        bytes memory data = abi.encodeWithSelector(c.setRewardDistributor.selector, newDistributor);
        (bool ok, ) = address(c).call(abi.encodePacked(data, abi.encode()));
        reverted = !ok;
        // For the original contract P, if caller is not the owner, the call must revert regardless of who caller is.
        // We cannot change msg.sender here, but we assert the general rule over the `caller` parameter: when caller != owner,
        // the call should be observed as reverted (reverted==true). This captures that only the owner can succeed.
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newDistributor) public payable {
        require(caller != address(0));
        // We cannot change msg.sender in this test, so we express the intended caller by
        // observing behavior: when the caller is not the owner, the call must revert on P.
        // Make the call as this contract (which is not necessarily owner). The rule will
        // relate the revert boolean to whether this contract is the owner by reading c.owner().
        bool reverted;
        try c.setRewardDistributor(newDistributor) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // On the original contract P, setRewardDistributor succeeds iff msg.sender == owner().
        // So assert that (reverted == (c.owner() != address(this))).
        assert(reverted == (c.owner() != address(this)));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newDistributor) public payable {
        // Precondition: the provided caller must be the owner of c according to its public owner() getter
        require(c.owner() == caller, "caller must be owner");

        // Make the call as the owner by using a low-level call from this contract forwarding msg.sender semantics is not possible,
        // so we instead check behavior by calling setRewardDistributor directly: when this test is executed in the harness,
        // it should be invoked with msg.sender equal to the owner; here we enforce via require above that the provided caller equals owner()
        // and then perform the call (the harness will call run with msg.sender == owner).
        bool reverted;
        try c.setRewardDistributor(newDistributor) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // In the original contract P the owner is allowed to call setRewardDistributor, so it must not revert when msg.sender is owner.
        assert(reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newDistributor) public payable {
        // restrict to callers that are the owner of c
        require(c.owner() == msg.sender, "caller must be owner");
        bool reverted;
        try c.setRewardDistributor(newDistributor) { reverted = false; } catch { reverted = true; }
        // On the original contract P the owner can call setRewardDistributor successfully, so reverted must be false
        assert(reverted == false);
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: an arbitrary address to use as reward token and an attacker address
    function testFuzz_property(address rewardToken, address distributorAttacker) public {
        // admissibility: rewardToken must be non-zero and distinct from contract to be meaningful
        vm.assume(rewardToken != address(0));

        // initially rewardDistributor was set to address(this) in setUp()
        address before = c.rewardDistributor();

        // only owner can call addReward in reference; setUp deployer is owner (this)
        // call addReward from owner
        c.addReward(rewardToken);

        // After addReward completes, the reference contract preserves rewardDistributor
        // We assert that rewardDistributor is still equal to the original value
        // The buggy mutant changes setRewardDistributor authorization, but that does not affect addReward itself.
        // However the mutant allows the current rewardDistributor to change the distributor later; to ensure the
        // assertion is universal for the reference and falsifiable for the mutant, we now attempt to have
        // the distributorAttacker call setRewardDistributor to itself. In the reference onlyOwner can set it,
        // so this call must fail (or at least not change the distributor). In the mutant, if distributorAttacker
        // equals the current distributor it would succeed; the fuzzer can choose distributorAttacker==before to
        // trigger the mutant change. We perform the call with a prank and then check the stored distributor.

        // Try to set reward distributor to distributorAttacker from that address
        // Fund and impersonate distributorAttacker to simulate call if it were allowed
        vm.deal(distributorAttacker, 1 wei);
        vm.prank(distributorAttacker);
        bool ok;
        // use try/catch via low-level call to capture both revert and success without using vm.expectRevert
        (ok, ) = address(c).call(abi.encodeWithSelector(c.setRewardDistributor.selector, distributorAttacker));

        // Single assertion: rewardDistributor must remain equal to before for the reference for ALL inputs;
        // the mutant can be made to change it when distributorAttacker == before (fuzzer can find such input),
        // causing this assertion to fail on the mutant for some inputs.
        assertTrue(c.rewardDistributor() == before);
    }
}
